<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { ArrowLeft, Bot, Download, ExternalLink, FileCheck2 } from '@lucide/vue'
import { api, downloadExport } from '../api'
const route=useRoute();const router=useRouter();const id=Number(route.params.id)
const meeting=ref<any>(null);const minutes=ref<any>(null);const busy=ref(false);const error=ref('')
async function load(){try{const[m,v]=await Promise.all([api(`/meetings/${id}`),api(`/meetings/${id}/minutes`)]);meeting.value=m;minutes.value=v.current}catch(e:any){error.value=e.message}}
async function review(){busy.value=true;try{const run=await api(`/meetings/${id}/review-runs`,{method:'POST'});router.push(`/reviews/${run.id}`)}catch(e:any){error.value=e.message}finally{busy.value=false}}
async function exportFile(format:'docx'|'pdf'){try{await downloadExport(id,format)}catch(e:any){error.value=e.message}}
const sections=(content:any)=>[{title:'会议决策',key:'decisions'},{title:'行动项',key:'action_items'},{title:'待确认',key:'open_questions'},{title:'风险',key:'risks'}].map(v=>({...v,items:content?.[v.key]||[]}))
onMounted(load)
</script>
<template><div v-if="!meeting&&!error" class="loading">LOADING MINUTES…</div><div v-else-if="error&&!meeting" class="notice error">{{error}}</div><div v-else><section class="page-heading"><div><button class="button compact" @click="router.push(`/meetings/${id}`)"><ArrowLeft :size="16"/>会议详情</button><div class="eyebrow" style="margin-top:24px">Minutes / {{minutes?`V${minutes.version}`:'none'}}</div><h1>结论旁边，<br>就是它的证据。</h1><p>{{meeting.title}}</p></div><div style="display:flex;gap:9px;flex-wrap:wrap"><button class="button" :disabled="!minutes" @click="exportFile('docx')"><Download :size="16"/>Word</button><button class="button" :disabled="!minutes" @click="exportFile('pdf')"><Download :size="16"/>PDF</button></div></section><div v-if="error" class="notice error" style="margin-bottom:16px">{{error}}</div><div v-if="!minutes" class="empty">还没有会议纪要。请先在会议详情生成。</div><div v-else class="minutes-layout"><article class="minutes-document"><header><div class="kicker">{{meeting.starts_at.slice(0,10)}} · Version {{minutes.version}}</div><h2 style="font-size:clamp(32px,4vw,56px);margin-top:12px">{{meeting.title}}</h2><span :class="['status',minutes.status==='approved'?'':'warning']">{{minutes.status}}</span></header><section><h3>会议摘要</h3><p style="font-size:18px;color:var(--ink)">{{minutes.content.summary}}</p></section><section v-for="section in sections(minutes.content)" :key="section.key"><h3>{{section.title}}</h3><div v-if="!section.items.length" class="notice">暂无{{section.title}}</div><article v-for="(item,index) in section.items" :key="index" class="minutes-item"><p>{{item.text||item.title||item.summary}}</p><p v-if="section.key==='action_items'" style="font-size:12px;margin-top:7px">负责人 {{item.owner||'待确认'}} · 截止 {{item.due||'待确认'}}</p><div class="evidence-links"><RouterLink v-for="segmentId in item.evidence_segment_ids" :key="segmentId" :to="`/meetings/${id}/transcript#segment-${segmentId}`">SEG {{segmentId}} <ExternalLink :size="9"/></RouterLink></div></article></section></article><aside class="side-sticky"><article class="card review-cta"><Bot :size="28"/><h2 style="margin-top:28px">让 Agent 找出遗漏，不替你做决定。</h2><p>审校会检查无证据结论、缺少负责人的行动项和内容完整性。修订稿需人工批准。</p><button class="button" style="color:white;border-color:#667" :disabled="busy" @click="review"><FileCheck2 :size="17"/>{{busy?'正在创建运行…':'启动智能复核'}}</button></article><article class="card" style="margin-top:16px"><div class="kicker">Trace contract</div><h3 style="margin-top:12px">证据引用不可伪造</h3><p>后端只保留真实存在的片段 ID；Agent 返回未知引用时会被过滤。</p></article></aside></div></div></template>
